<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import AuthShell from '@/layouts/AuthShell.vue'; import { connect } from '@/services/connect'; import { friendlyError } from '@/services/errors'
const name=ref(''),email=ref(''),password=ref(''),confirm=ref(''),token=ref(''),error=ref(''),busy=ref(false),router=useRouter()
async function submit(){ error.value=''; if(password.value!==confirm.value){error.value='As senhas não conferem.';return} busy.value=true; try{await connect.setup({name:name.value,email:email.value,password:password.value},token.value);router.push('/login')}catch(e){error.value=friendlyError(e)}finally{busy.value=false}}
</script>
<template><AuthShell><div class="auth-title"><h1>Primeiro acesso</h1><p>Crie a conta responsável pela administração do Connect|API.</p></div><div v-if="error" class="alert error">{{ error }}</div><form class="form-stack" @submit.prevent="submit"><label class="field"><span>Nome</span><input v-model="name" required/></label><label class="field"><span>E-mail</span><input v-model="email" type="email" required/></label><label class="field"><span>Senha</span><input v-model="password" type="password" minlength="12" required/></label><label class="field"><span>Confirmar senha</span><input v-model="confirm" type="password" minlength="12" required/></label><label class="field"><span>Código de configuração</span><input v-model="token" type="password" required/></label><button class="btn primary full" :disabled="busy">{{busy?'Criando...':'Criar acesso'}}</button></form></AuthShell></template>
